function tau_M_lpf = mfun_ovhz_torque_filter(enable, tau_M, p)
%MFUN_OVHZ_TORQUE_FILTER Block tau_M_lpf of the control system.
%   Generated by motulator_export from the MATLAB port of motulator. The parameters are
%   the fields of the struct p (from the mask, [] as NaN). The state is in persistent
%   variables. The inputs without direct feedthrough come through unit delays, so the
%   update of the state with them is done at the next call.
persistent self self_init pending enable_prev
if isempty(self)
    % Low-pass-filtered torque estimate
    self = 0;
    self_init = self;
    pending = false;
    enable_prev = 0;
end
% Update of the previous sampling period with its inputs (the inputs
% tau_M through unit delays)
if pending
    if enable_prev > 0
        self = self + p.T_s*p.alpha_f*(tau_M - self);
    else
        self = self_init;
    end
end
pending = true;
enable_prev = enable;
% Disabled: the algorithm is not run
if ~(enable > 0)
    tau_M_lpf = 0;
    return
end
tau_M_lpf = self;
end
